-- generated by dip from the healthcare.lab_results contract, version 1. Do not edit: change the contract, then
-- python -m dip contracts dbt healthcare.lab_results --write
{{ config(schema='silver', materialized='view', tags=['file_feed', 'healthcare.lab_results', 'generated']) }}

-- Silver: every accepted row of every healthcare.lab_results file, typed by the contract.
with deliveries as (
    select distinct on (d.file_sha256)
        d.file_sha256,
        d.source_key,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) as file_date,
        d.received_at
    from {{ source('ops', 'intake_delivery') }} as d
    where d.feed = 'healthcare.lab_results'
    order by
        d.file_sha256,
        coalesce(d.file_date, (d.received_at at time zone 'UTC')::date) desc,
        d.received_at desc,
        d.source_key desc
)

select
    b.file_sha256,
    b.row_number,
    d.source_key,
    d.file_date,
    d.received_at,
    f.contract_version,
    b.record ->> 'result_id' as "result_id",
    b.record ->> 'patient_ref' as "patient_ref",
    (b.record ->> 'collected_date')::date as "collected_date",
    b.record ->> 'loinc_code' as "loinc_code",
    (b.record ->> 'result_value')::numeric as "result_value",
    b.record ->> 'unit' as "unit",
    b.record ->> 'abnormal_flag' as "abnormal_flag",
    b.record ->> 'ordering_provider' as "ordering_provider"
from {{ source('bronze', 'csv_record') }} as b
inner join {{ source('ops', 'intake_file') }} as f
    on f.feed = b.feed and f.file_sha256 = b.file_sha256
inner join deliveries as d on d.file_sha256 = b.file_sha256
where b.feed = 'healthcare.lab_results'
